def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = 18.0 if hp > 3 else 45.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    strong_count = 0
    weak_count = 0
    desperate_opp = 0
    rich_opp = 0

    for opp in alive_opponents:
        if float(opp.get('budget', 0.0)) >= 500:
            rich_opp += 1
        if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 10)) <= 4:
            desperate_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            b = float(bid)
            prev_bids.append(b)
            if b >= 85:
                strong_count += 1
            if b <= 30:
                weak_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    if hp <= 2 or no_water_days >= 2:
        emergency = max(92.0, highest_prev + 4.0, 70.0 + 18.0 * scarcity)
        return float(max(0.0, min(budget, emergency)))

    if hp <= 4 or no_water_days >= 1:
        urgent = max(72.0, min(98.0, highest_prev + 2.0), 62.0 + 16.0 * scarcity)
        return float(max(0.0, min(budget, urgent)))

    base = 24.0 + 18.0 * scarcity

    if strong_count >= 2:
        base -= 6.0
    elif strong_count == 1:
        base += 4.0

    if weak_count >= 2:
        base += 3.0

    if desperate_opp >= 2:
        base += 5.0

    if rich_opp >= 2:
        base -= 3.0

    if avg_prev > 0:
        if avg_prev >= 90:
            base = min(base, 28.0 + 10.0 * scarcity)
        elif avg_prev <= 35:
            base = max(base, avg_prev + 4.0)

    if day >= 8 and hp >= 6:
        base -= 4.0

    if budget < 120:
        base = min(base, 32.0)

    bid = max(12.0, base)
    bid = min(budget, bid)
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return 10.0

    avg_prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            avg_prev_bids.append(prev['bid'])

    market_pressure = max(avg_prev_bids) if avg_prev_bids else 80.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], market_pressure * 1.15)
    elif supply < 16:
        bid = min(my_status['budget'], market_pressure * 1.05)
    else:
        bid = min(my_status['budget'], market_pressure * 0.8)

    return max(1.0, min(140.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return int(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Read yesterday bids only for immediate reaction
    yesterday_bids = []
    highest_prev_bid = None
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            yesterday_bids.append(b_val)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Estimate how many shares of water could exist; use to calibrate bid aggressiveness.
    # Avoid float indices; just compute scalars.
    # If supply is near max, competition is lower.
    supply_factor = 0.5
    if supply <= float(MIN_SUPPLY):
        supply_factor = 0.75
    elif supply >= float(MAX_SUPPLY):
        supply_factor = 0.45
    else:
        # linear between
        supply_factor = 0.75 - (supply - float(MIN_SUPPLY)) * (0.75 - 0.45) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))

    # Identify if any opponent shows signs of being in trouble (low hp / no water days yesterday)
    trouble_count = 0
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        prev_hp_after = prev.get('hp_after', None)
        prev_no_water_days = prev.get('status', None)
        # status may encode no-water days; be conservative
        if prev_hp_after is not None:
            try:
                if float(prev_hp_after) <= 2.0:
                    trouble_count += 1
            except Exception:
                pass

    # Strategy:
    # - If yesterday highest bid was very high, competition is strong; bid slightly above a safe baseline.
    # - If my hp is low, bid more to secure survival.
    # - Otherwise bid moderate to avoid Cindy/Eric-style overspending.
    baseline = DAILY_SALARY * 0.45

    if highest_prev_bid is not None:
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = DAILY_SALARY * 0.55 + (highest_prev_bid - DAILY_SALARY * 0.85) * 0.15
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            target = DAILY_SALARY * 0.5
        else:
            target = DAILY_SALARY * 0.42
    else:
        target = baseline

    # Adjust for supply and my hp
    if my_hp <= 2.0:
        target = max(target, DAILY_SALARY * 0.85)
    elif my_hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.65)

    target *= supply_factor

    # If multiple opponents appear to have been pressured (trouble_count), we can slightly reduce to save budget.
    if trouble_count >= 2:
        target *= 0.9

    # Cap by budget and keep within reasonable range
    bid = int(min(my_budget, max(0.0, target)))

    # Ensure nonzero bid when budget allows and supply is low (to avoid losing all days)
    if bid <= 0 and my_budget > 0:
        bid = int(min(my_budget, DAILY_SALARY * 0.25))

    return bid
